query:
query GiftGuideReleaseInventory($id: ID!, $after: String) {
 shop { id name myshopifyDomain ianaTimezone }
 shopLocales { locale primary published }
 markets(first:50, after:$after) { nodes { id name } pageInfo { hasNextPage endCursor } }
 article(id:$id) { id title handle body summary tags templateSuffix isPublished publishedAt updatedAt createdAt author { name } blog { id handle title } image { id url altText width height } }
 translatableResource(resourceId:$id) { resourceId translatableContent { key locale value digest type } }
}
